import java.io.InputStreamReader;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImageRotator {

    public static void main(String[] args) {
        if (args.length < 2) {
            System.err.println("Usage: java ImageRotator <photo_file_path> <angle>");
            System.exit(1);
        }

        String filePath = args[0];
        String angleStr = args[1];

        File inputFile = new File(filePath);
        if (!inputFile.exists()) {
            System.err.println("Error: Input file does not exist at " + filePath);
            System.exit(1);
        }

        try {
            double angle = Double.parseDouble(angleStr);
            String outputFilePath = generateOutputFilePath(filePath);

            ProcessBuilder processBuilder = new ProcessBuilder("convert", filePath, "-rotate", String.valueOf(angle), outputFilePath);
            processBuilder.redirectErrorStream(true);
            Process process = processBuilder.start();

            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            StringBuilder output = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append(System.lineSeparator());
            }

            int exitCode = process.waitFor();

            if (exitCode == 0) {
                System.out.println("Image rotated successfully.");
                displayImage(outputFilePath);
            } else {
                System.err.println("Error: Image processing command failed with exit code " + exitCode);
                System.err.println("Command Output:\n" + output.toString());
            }
        } catch (NumberFormatException e) {
            System.err.println("Error: The rotation angle must be a valid number.");
        } catch (IOException | InterruptedException e) {
            System.err.println("Error executing command: " + e.getMessage());
        }
    }

    private static String generateOutputFilePath(String originalPath) {
        Path path = Paths.get(originalPath);
        String fileName = path.getFileName().toString();
        int dotIndex = fileName.lastIndexOf('.');
        String baseName = (dotIndex == -1) ? fileName : fileName.substring(0, dotIndex);
        String extension = (dotIndex == -1) ? "" : fileName.substring(dotIndex);

        String newFileName = baseName + "_rotated" + extension;
        if (path.getParent() != null) {
            return path.getParent().resolve(newFileName).toString();
        }
        return newFileName;
    }

    private static void displayImage(String imagePath) {
        File file = new File(imagePath);
        try {
            if (Desktop.isDesktopSupported() && Desktop.getDesktop().isSupported(Desktop.Action.OPEN)) {
                Desktop.getDesktop().open(file);
            } else {
                System.err.println("Desktop operations not supported. Rotated image saved at: " + file.getAbsolutePath());
            }
        } catch (IOException e) {
            System.err.println("Error displaying the image: " + e.getMessage());
        }
    }
}

